/* Generated from project-watch-cevni-question-bank-1.70.0.json. Data only. */
window.PW_CEVNI_LIVE_QUESTIONS={"baseChecks":[["Which statement is safest before entering an unfamiliar CEVNI waterway?",["Check the applicable local rules and competent-authority information","Assume CEVNI removes every local rule","Use COLREGs only"],0],["Why are vessel dimensions especially important inland?",["They can determine whether depth, width and headroom restrictions can be met","They replace the need for a lookout","They determine AIS right of way"],0],["What does Annex 7 group B contain?",["Mandatory signs","Prohibitory signs","Informative signs"],0],["What is the correct recognition method?",["Combine the visual signal with vessel/aspect/operation context","Guess from colour alone","Let AIS replace visual recognition"],0],["What do three short blasts mean?",["I am going astern","I am altering to port","Caution"],0],["How should Inland AIS be treated?",["As an aid, not a replacement for lookout","As a right-of-way display","As proof of another vessel’s intentions"],0],["Before entering a lock approach, what should you do?",["Check local instructions and traffic arrangements","Assume seagoing rules are enough","Ignore signs if your craft is small"],0],["If AIS and the visual picture disagree, what is the best principle?",["Verify using all available means and maintain lookout","Trust AIS automatically","Ignore the visual picture"],0],["Which statement about pollution and waste is correct?",["It is within the CEVNI framework","It is only a sea-going issue","It is unrelated to inland navigation"],0]],"mock":[["CEVNI primarily provides what?",["Core harmonised rules for inland-waterway traffic","A global ocean racing code","A chart datum standard"],0],["Which statement about local rules is correct?",["CEVNI removes all local rules","Applicable national/regional/local provisions still need checking","Local rules matter only to commercial vessels"],1],["Annex 7 group A contains which signs?",["Prohibitory","Informative","Recommendatory"],0],["Annex 7 group B contains which signs?",["Restrictive","Mandatory","Auxiliary only"],1],["Annex 7 group C contains which signs?",["Restrictive","Prohibitory","Informative"],0],["Annex 7 group D contains which signs?",["Recommendatory","Mandatory","Distress"],0],["Annex 7 group E contains which signs?",["Informative","Prohibitory","Sound"],0],["A short blast lasts approximately:",["1 second","4 seconds","10 seconds"],0],["A long blast lasts approximately:",["Quarter second","4 seconds","12 seconds"],1],["A very short blast in the danger series lasts about:",["Quarter second","One second","Four seconds"],0],["One long blast means:",["Caution","Altering to starboard","Going astern"],0],["One short blast means:",["Altering course to starboard","Altering course to port","Unable to manoeuvre"],0],["Two short blasts mean:",["Altering course to port","Going astern","Caution"],0],["Three short blasts mean:",["Going astern","Turning to starboard","Do not approach"],0],["Four short blasts mean:",["Unable to manoeuvre","Entry permitted","Overtaking requested"],0],["A series of at least six very short blasts warns of:",["Imminent danger of collision","A lock opening","A recommended route"],0],["A.1 means:",["No entry","No anchoring","No turning"],0],["A.2 means:",["No overtaking","No berthing","No wash"],0],["B.1 requires a vessel to:",["Proceed in the direction shown","Stop immediately","Sound one long blast"],0],["B.7 requires a vessel to:",["Give a sound signal","Call on VHF","Display a blue board"],0],["C.1 warns that:",["Depth of water is limited","Headroom is limited","Width is limited"],0],["D.1 identifies:",["A recommended opening","A prohibited opening","A ferry crossing"],0],["E.1 means:",["Entry permitted","No entry","Berthing prohibited"],0],["E.2 identifies:",["An overhead cable crossing","A weir","A ferry"],0],["Before entering a lock approach you should:",["Check local instructions and traffic arrangements","Assume seagoing rules are sufficient","Ignore signs if under 20 m"],0],["Inland AIS should be treated as:",["An aid to navigation, not a replacement for lookout","A right-of-way display","A guarantee of intentions"],0],["Waterway marking can indicate:",["Fairway limits and hazards","Only marina entrances","Only borders"],0],["A recommendatory sign should be:",["Taken into account as navigation guidance","Treated as distress","Ignored by pleasure craft"],0],["Pollution and waste provisions are:",["Within the scope of CEVNI","Outside inland navigation rules","Only relevant at sea"],0],["Radiotelephony provisions are:",["Part of the CEVNI framework","Not used inland","Only a weather service"],0]],"scenarios":[{"visual":"rules","label":"LOCAL RULES","q":"You approach an unfamiliar European inland waterway. What should be established before relying on Project Watch teaching?","a":["The applicable national/local navigation rules and competent-authority information","Only the COLREG steering rules","Only your chartplotter route"],"c":0,"e":"CEVNI is a harmonised basis, but applicable national, regional and local provisions must be checked."},{"visual":"sign","label":"MANDATORY SIGN","q":"A mandatory waterway sign conflicts with your preferred route. What is the correct training principle?","a":["Ignore it if AIS shows no traffic","Comply with the sign and assess the local navigation situation","Follow the route because your vessel is small"],"c":1,"e":"A mandatory sign prescribes an action or direction. It is not merely a route suggestion."},{"visual":"lock","label":"LOCK APPROACH","q":"You are approaching a lock with uncertain VHF/reporting arrangements. Best action?","a":["Proceed into the approach and work it out later","Sound five short blasts automatically","Check the applicable lock instructions, radio channel and local procedure before committing"],"c":2,"e":"Constrained infrastructure requires early preparation and compliance with local operating instructions."},{"visual":"ais","label":"AIS + LOOKOUT","q":"AIS information and the visual situation do not agree. What is the correct principle?","a":["Treat AIS as definitive","Maintain lookout and verify using all available means","Continue at the same speed because AIS is mandatory"],"c":1,"e":"Inland AIS is an aid to navigation, not a replacement for lookout or judgement."}],"recognition":[{"family":"I","cue":"A 14 m craft is authorized to carry 20 passengers.","choices":["Small craft","Passenger vessel","Water bike","Pushed barge"],"correct":1,"why":"Length alone does not make it small craft. Craft authorized for more than 12 passengers are excluded from the small-craft definition."},{"family":"I","cue":"A yacht is moving with sails set while its engine is also driving the propeller.","choices":["Sailing vessel","Motorized vessel","Floating equipment","Shipborne barge"],"correct":1,"why":"For the CEVNI definition, using sail and mechanical propulsion at the same time means it is treated as a motorized vessel."},{"family":"I","cue":"A floating dredger is carrying machinery and working in the waterway.","choices":["Floating equipment","Passenger vessel","Ferry-boat","Sports craft"],"correct":0,"why":"Working floating structures carrying machinery, such as dredging or lifting plant, are floating equipment."},{"family":"I","cue":"A craft provides a regular crossing service from one bank to the other and is classed by the competent authority for that service.","choices":["Ferry-boat","Towed convoy","Water bike","Floating establishment"],"correct":0,"why":"The service and competent-authority classification identify a ferry-boat; self-propulsion is not required."},{"family":"II","cue":"A motorized vessel is behind a rigidly connected barge and propels the assembly forward.","choices":["Towed convoy","Pushed convoy","Side-by-side formation","Floating establishment"],"correct":1,"why":"At least one vessel is ahead of the motorized vessel propelling a rigid assembly: that is a pushed convoy."},{"family":"II","cue":"Two vessels are coupled alongside each other; the powered vessel propels the formation and neither vessel is positioned ahead of it.","choices":["Side-by-side formation","Pushed convoy","Towed convoy","Shipborne barge"],"correct":0,"why":"Alongside coupling with no vessel ahead of the propelling motorized vessel is the defining layout of a side-by-side formation."},{"family":"II","cue":"A tug pulls two barges astern.","choices":["Pushed convoy","Towed convoy","Side-by-side formation","Passenger vessel"],"correct":1,"why":"The tug and the craft being towed form a towed convoy."},{"family":"III","cue":"You hear a blast lasting about four seconds.","choices":["Short blast","Long blast","Very short blast","Three-tone signal"],"correct":1,"why":"CEVNI defines a long blast as approximately four seconds; a short blast is approximately one second."},{"family":"III","cue":"A light flashes around 110 times per minute.","choices":["Ordinary light","Scintillating light","Quick scintillating light","Strong light"],"correct":2,"why":"Quick scintillating is 100–120 flashes per minute; ordinary scintillating is 40–60."},{"family":"III","cue":"You hear at least six rapid quarter-second blasts with similarly short gaps.","choices":["Series of very short blasts","Three-tone signal","Series of long blasts","One short blast"],"correct":0,"why":"That rapid pattern is the defined series of very short blasts."},{"family":"IV","cue":"A vessel is not anchored, not made fast to shore and not grounded, although its speed over the ground is currently zero.","choices":["Stationary","Under way / proceeding","Floating establishment","Grounded"],"correct":1,"why":"Under way/proceeding is defined by not being anchored, made fast or grounded; zero speed does not by itself make the vessel stationary."},{"family":"IV","cue":"Fog has reduced how far the boatmaster can see.","choices":["Night","Reduced visibility","Safe speed","Fairway"],"correct":1,"why":"Fog is a stated example of reduced visibility."},{"family":"IV","cue":"Only the navigable portion of a wider inland waterway can safely be used by vessels.","choices":["Waterway","Fairway","Right bank","Port"],"correct":1,"why":"The fairway is the part of the waterway that can actually be used for navigation."},{"family":"IV","cue":"On a river, you need to identify the left bank.","choices":["Face toward the source","Face from source toward the mouth","Use the vessel heading","Use the wind direction"],"correct":1,"why":"For rivers, left and right banks are determined while facing from the source toward the mouth."},{"family":"IV","cue":"The current has temporarily reversed in a tidal reach, but the charted river direction remains established.","choices":["Upstream/downstream automatically reverse","Reference direction remains based on source/mouth","Both directions become undefined","Use vessel heading instead"],"correct":1,"why":"CEVNI upstream remains toward the source even on tidal sections where current direction changes."},{"family":"IV","cue":"A speed lets the vessel manoeuvre safely and stop within the distance demanded by the actual circumstances.","choices":["Maximum speed","Safe speed","Minimum steerage speed","Fairway speed"],"correct":1,"why":"Safe speed is contextual: it must permit safe navigation/manoeuvring and stopping within the required distance."}],"context102":[{"title":"Lock approach — authority and fitness","situation":"You are approaching a busy lock. The nominated boatmaster is severely fatigued and another qualified person is available on board.","prompt":"What is the correct operational decision?","choices":["Continue because nomination overrides fatigue","Transfer effective charge to a qualified, fit person before continuing","Let an unqualified crew member take charge temporarily"],"correct":1,"why":"Article 1.02 requires a qualified boatmaster whose faculties are not impaired by fatigue or intoxication. Operational responsibility must be carried by someone fit to exercise it."},{"title":"Pushed convoy — who leads?","situation":"A powered pusher is rigidly connected behind two barges and provides the main propulsion. The formation is approaching a restricted reach.","prompt":"Who is the default convoy boatmaster under the CEVNI framework?","choices":["The boatmaster of the pusher providing the main propulsion","The boatmaster of the forward barge","Whichever boatmaster first sees the restriction"],"correct":0,"why":"For a pushed convoy, the harmonised rule points to the boatmaster of the pusher providing the main propulsion, subject to any applicable local variation."},{"title":"Towed convoy — retained duty","situation":"A convoy boatmaster orders a towed vessel to maintain position. Its own boatmaster then sees an immediate local hazard affecting that vessel.","prompt":"What should happen?","choices":["Do nothing until a new convoy order arrives","Take the steps required by the circumstances while remaining within the convoy authority structure","Leave the convoy immediately without communication"],"correct":1,"why":"Convoy authority does not remove the other boatmasters’ responsibility to take steps required by circumstances for proper handling of their own vessels."},{"title":"Floating equipment in operation","situation":"A dredger is working in the fairway. Its nominated boatmaster proposes supervising from the bank by radio.","prompt":"Is that sufficient for the Article 1.02 presence requirement?","choices":["Yes, if radio coverage is good","No; the boatmaster is required on board while the floating equipment is operating","Yes, provided another vessel is nearby"],"correct":1,"why":"The boatmaster of floating equipment must be on board whenever the equipment is in operation."},{"title":"Moored vessel — boatmaster absent","situation":"A vessel is secured alongside overnight. The boatmaster has left, but a person is assigned the required watch and surveillance duty.","prompt":"Who carries the immediate compliance responsibility described by Article 1.02?","choices":["Nobody until the boatmaster returns","The person responsible for watch and surveillance","The harbour master automatically"],"correct":1,"why":"Where the boatmaster is absent from a moored vessel or assembly, Article 1.02 points first to the person responsible for watch and surveillance under Article 7.08."},{"title":"Special-risk stretch","situation":"A qualified boatmaster reaches a waterway stretch for which the competent authority requires specific additional authorization.","prompt":"What is the correct action?","choices":["Proceed because the general qualification is enough everywhere","Ensure the required specific authorization is held before navigating the stretch","Proceed only at reduced speed"],"correct":1,"why":"A general qualification does not displace a competent authority’s specific authorization requirement for identified higher-risk stretches."}],"context":[{"title":"Passenger launch at the lock approach","situation":"You are approaching a lock in a 13.5 m commercial launch. The vessel is authorized to carry 18 passengers. Another skipper casually calls it “small craft” because it is under 20 metres.","task":"Which classification should guide your CEVNI decisions?","choices":["Treat it as small craft because length is under 20 m","Treat the passenger authorization as an exclusion from small craft","Treat it as floating equipment","Length and passenger authorization are irrelevant"],"correct":1,"why":"The under-20 m threshold is not the whole definition. A vessel authorized to carry more than 12 passengers is excluded from the CEVNI small-craft category."},{"title":"Sailing yacht using its engine","situation":"A yacht is proceeding along a confined inland reach with sails set. Its engine is engaged and driving the propeller while it manoeuvres through traffic.","task":"For the CEVNI vessel-type definition, how should you classify it?","choices":["Sailing vessel only","Motorized vessel while mechanical propulsion is being used","Stationary vessel","Side-by-side formation"],"correct":1,"why":"Using sail and mechanical propulsion at the same time places the vessel within the motorized-vessel definition. That classification matters when later rules assign responsibilities."},{"title":"Worksite ahead","situation":"A dredging unit carrying excavating machinery is operating near the edge of the navigable channel. It is floating, but its principal role is carrying and operating working machinery.","task":"What definition should you recognise before interpreting later marks and signals?","choices":["Passenger vessel","Floating equipment","Ferry-boat","Small craft"],"correct":1,"why":"A floating structure carrying working machinery such as dredging plant is floating equipment. Recognising the type prepares the learner for its later visual signals and operating restrictions."},{"title":"Formation entering a bend","situation":"A powered vessel is rigidly connected behind a barge and propels the combined unit forward toward a bend. The barge is ahead of the propelling vessel.","task":"What formation are you looking at?","choices":["Towed convoy","Pushed convoy","Side-by-side formation","Floating establishment"],"correct":1,"why":"A rigid assembly with at least one vessel positioned ahead of the motorized vessel that propels it is a pushed convoy."},{"title":"Coupled vessels alongside","situation":"Two vessels are secured alongside one another. One motorized vessel propels the pair, and no vessel in the formation is positioned ahead of the propelling vessel.","task":"Which formation definition applies?","choices":["Pushed convoy","Side-by-side formation","Towed convoy","Grounded vessels"],"correct":1,"why":"The alongside arrangement, with no vessel ahead of the propelling motorized vessel, is a side-by-side formation."},{"title":"Stopped in the fairway","situation":"Your vessel has reduced power to zero and is momentarily making no speed over the ground while waiting for traffic. It is not anchored, made fast to shore or grounded.","task":"Which CEVNI status still applies?","choices":["Stationary","Under way / proceeding","Grounded","Floating establishment"],"correct":1,"why":"Zero speed alone does not make a vessel stationary for this definition. If it is not anchored, made fast or grounded, it remains under way/proceeding."},{"title":"Fog closes in","situation":"Visibility deteriorates rapidly in fog. You can no longer see far enough ahead to navigate using the same assumptions you used in clear conditions.","task":"Which pair of Article 1.01 concepts should immediately frame your thinking?","choices":["Reduced visibility and safe speed","Night and maximum speed","Fairway and ferry-boat","Scintillating light and pushed convoy"],"correct":0,"why":"Fog is reduced visibility. Safe speed is contextual and must allow safe manoeuvring and stopping within the distance required by the actual circumstances."},{"title":"River direction after the tide turns","situation":"You are on a tidal river. The current has reversed, but you need to identify the left bank and decide what “upstream” means in the CEVNI terminology.","task":"Which reference should you use?","choices":["The instantaneous direction of the tidal current","The vessel’s present heading","The established source-to-mouth river direction","Whichever bank has the navigation marks"],"correct":2,"why":"River bank orientation is referenced while facing from source toward mouth, and upstream remains toward the source even where a tidal current can reverse."}],"responsibility":[{"title":"Ordinary vessel","situation":"A motorized inland vessel is preparing to get under way. Several experienced crew members are aboard, but nobody has been appointed to exercise the regulatory authority of the vessel.","prompt":"What is the Article 1.02 problem?","choices":["Every vessel must be placed under the authority of a suitably qualified boatmaster","Any experienced crew member automatically becomes boatmaster","A boatmaster is required only for a convoy","The shore operator carries the navigation responsibility"],"correct":0,"why":"Article 1.02 places the vessel under the authority of a suitably qualified person — the boatmaster. Experience aboard does not by itself replace that role."},{"title":"Specific-risk stretch","situation":"A vessel has several qualified boatmasters aboard and is approaching a stretch for which the competent authority requires a specific authorization because of identified risks.","prompt":"Who must hold the specific authorization for the stretch?","choices":["Every boatmaster anywhere on board","Only the owner of the vessel","The boatmaster on duty in the wheelhouse","Any crew member nominated by the operator"],"correct":2,"why":"Where the specific authorization is required and several boatmasters are assigned, the boatmaster actually on duty in the wheelhouse must hold it."},{"title":"One motorized vessel in a convoy","situation":"A convoy contains several craft but only one motorized vessel.","prompt":"Who is the boatmaster of the convoy under the Article 1.02 allocation rule?","choices":["The boatmaster of the motorized vessel","The oldest boatmaster in the convoy","The boatmaster of the rearmost craft","The convoy has no single boatmaster"],"correct":0,"why":"Where a convoy has only one motorized vessel, the boatmaster of that motorized vessel is the boatmaster of the convoy."},{"title":"Towed convoy — auxiliary tug leads","situation":"Two motorized vessels are towing in line. The vessel at the very front is only a temporary auxiliary tug.","prompt":"Which boatmaster carries convoy authority?","choices":["The temporary auxiliary tug’s boatmaster","The boatmaster of the second vessel","The boatmaster of the last towed vessel","Both leading boatmasters equally"],"correct":1,"why":"The usual leading-vessel rule has an exception where the leading vessel is a temporary auxiliary tug; in that case the boatmaster of the second vessel is the convoy boatmaster."},{"title":"Towed convoy — main traction","situation":"Two motorized towing vessels are not in line. One of them clearly provides the main traction for the convoy.","prompt":"Who is the convoy boatmaster?","choices":["The boatmaster of whichever vessel is furthest ahead","The boatmaster of the vessel providing the main traction","The boatmaster chosen by the towed vessel","There is no convoy boatmaster until the vessels form a line"],"correct":1,"why":"For this formation, Article 1.02 assigns convoy authority to the boatmaster of the vessel providing the main traction."},{"title":"Two pushers side-by-side","situation":"A pushed convoy is propelled by two pushers operating side-by-side. One pusher is providing the main propulsion.","prompt":"Who is the convoy boatmaster?","choices":["The boatmaster of the pusher providing the main propulsion","The boatmaster of the left-hand pusher in every country","Both pusher boatmasters automatically share equal authority","The boatmaster of the foremost pushed vessel"],"correct":0,"why":"The harmonized CEVNI rule points to the pusher providing the main propulsion. National or regional deviations are a separate local-rule layer and must be checked for the actual waterway."},{"title":"Under way without the boatmaster","situation":"A vessel is under way. The qualified boatmaster has gone ashore briefly while another crew member continues navigating.","prompt":"What does Article 1.02 require?","choices":["This is acceptable if the crew member has enough experience","The boatmaster must be on board while the vessel is under way","The boatmaster only needs to be reachable by radio","Presence is required only during lock operations"],"correct":1,"why":"When the vessel is under way, the boatmaster is required to be on board."},{"title":"Floating equipment operating","situation":"Floating equipment is operating on the waterway. Its boatmaster is supervising the operation remotely from the bank.","prompt":"Which Article 1.02 requirement applies?","choices":["Remote supervision is sufficient","The boatmaster must be on board whenever the floating equipment is in operation","A boatmaster is needed only while the equipment is moving","Only the equipment operator needs to be aboard"],"correct":1,"why":"Article 1.02 specifically requires the boatmaster of floating equipment to be on board whenever that equipment is in operation."},{"title":"Towed vessel receives an order","situation":"The convoy boatmaster gives an order to a towed vessel. The towed vessel’s own boatmaster sees an immediate local hazard requiring action for the proper handling of that vessel.","prompt":"What is the best description of the responsibility?","choices":["The towed vessel boatmaster must do nothing unless specifically ordered","The convoy boatmaster removes all responsibility from the other boatmasters","The towed vessel follows convoy orders but its boatmaster still takes steps required by the circumstances for proper handling","Responsibility transfers entirely to the vessel owner"],"correct":2,"why":"Convoy authority does not erase the duties of the other boatmasters. They obey the convoy boatmaster while still taking the steps required by circumstances for proper handling of their own vessels."},{"title":"Floating establishment","situation":"A floating establishment is stationary and is not navigating like an ordinary vessel.","prompt":"Does Article 1.02 still establish a responsibility structure?","choices":["No — Article 1.02 applies only to moving vessels","Yes — it is placed under the authority of a person responsible for observing the applicable provisions","Only if it carries passengers","Only while a tug is attached"],"correct":1,"why":"A floating establishment is also placed under the authority of a responsible person for observance of the applicable navigation provisions."},{"title":"Fatigue before taking the watch","situation":"A boatmaster is legally qualified but is severely fatigued before taking charge of the vessel.","prompt":"How does Article 1.02 treat this?","choices":["The certificate alone makes the boatmaster fit for duty","Fatigue matters only after an incident","The boatmaster’s faculties must not be impaired by fatigue or intoxication","The crew decides whether fatigue is relevant"],"correct":2,"why":"Qualification and fitness are separate requirements. Article 1.02 states that the boatmaster’s faculties must not be impaired by fatigue or intoxication."},{"title":"Moored vessel — boatmaster absent","situation":"A vessel is moored and has no boatmaster present. A person has been assigned responsibility for watch and surveillance under Article 7.08.","prompt":"Who carries the Article 1.02 compliance responsibility in this situation?","choices":["Nobody until the boatmaster returns","The person responsible for watch and surveillance","The nearest vessel’s boatmaster","The competent authority automatically"],"correct":1,"why":"For a moored vessel or assembly with no boatmaster, responsibility first falls to the person responsible for watch and surveillance under Article 7.08; if that person is absent, the rule then points to the operator and owner."}]};
